CAMBIOS = [('up-argus:\n\t@vagrant up defender client\n', 'up-argus:\n\t@vagrant up defender client etcd\n'), ('up:\n\t@vagrant up defender client suricata zeek wazuh\n', 'up:\n\t@vagrant up defender client suricata zeek wazuh etcd\n'), ('halt-argus:\n\t@vagrant halt defender client\n', 'halt-argus:\n\t@vagrant halt defender client etcd\n'), ('halt:\n\t@vagrant halt defender client suricata zeek wazuh\n', 'halt:\n\t@vagrant halt defender client suricata zeek wazuh etcd\n'), ('pipeline-start: test-provision-1 etcd-server-start\n\t@echo "⏳ Waiting for etcd-server to stabilize (Seed generation)..."\n\t@sleep 4\n\t@sleep 5\n\t@$(MAKE) ml-detector-start VERBOSE', 'pipeline-start: test-provision-1\n\t@$(MAKE) --no-print-directory etcd-vm-aviso  # [ETCD-VM-D317] avisa si la VM etcd no está sana; no para el arranque\n\t@$(MAKE) ml-detector-start VERBOSE'), ('pipeline-start-x86-libpcap: test-provision-1 etcd-server-start\n\t@echo "⏳ Waiting for etcd-server to stabilize (Seed generation)..."\n\t@sleep 4\n\t@sleep 5\n', 'pipeline-start-x86-libpcap: test-provision-1\n\t@$(MAKE) --no-print-directory etcd-vm-aviso  # [ETCD-VM-D317]\n'), ('\tvagrant up defender client suricata\n\tvagrant ssh defender -c "mkdir -p /vagrant/logs/lab && date -u > /vagrant/logs/lab/emecas_inicio.stamp"\n', '\tvagrant up defender client suricata etcd\n\tvagrant ssh defender -c "mkdir -p /vagrant/logs/lab && date -u > /vagrant/logs/lab/emecas_inicio.stamp"\n'), ('\t$(MAKE) emecas-frescura\n\t$(MAKE) test-all\n', '\t$(MAKE) emecas-frescura\n\t$(MAKE) etcd-vm-deploy  # [ETCD-VM-D317] binario + config + servicio en la VM etcd; falla si no queda sano\n\t$(MAKE) test-all\n'), ('etcd-server-status:\n\t@echo "════════════════════════════════════════════════════════════"\n\t@echo "etcd-server Status:"\n\t@vagrant ssh -c "pgrep -a -f etcd-server && echo \'✅ etcd-server: RUNNING\' || echo \'❌ etcd-server: STOPPED\'"\n\t@vagrant ssh -c "curl -s http://localhost:2379/health || echo \'⚠️  Not responding\'"\n\t@echo "════════════════════════════════════════════════════════════"\n', 'etcd-server-status:  # [ETCD-VM-D317] el etcd-server vive en la VM etcd (servicio systemd)\n\t@$(MAKE) --no-print-directory etcd-vm-estado\n'), ('etcd-server-start: etcd-server\n\t@echo "🚀 Starting etcd-server (Persistente)..."\n\t@vagrant ssh -c "tmux kill-session -t etcd-server 2>/dev/null || true"\n\t@vagrant ssh -c "tmux new-session -d -s etcd-server \'mkdir -p /vagrant/logs/lab && cd /vagrant && sudo env LD_LIBRARY_PATH=/usr/local/lib $(ETCD_SERVER_BUILD_DIR)/etcd-server >> /vagrant/logs/lab/etcd-server.log 2>&1\'"\n\t@sleep 2\n\t@$(MAKE) etcd-server-status\n\netcd-server-stop:\n\t@vagrant ssh -c "tmux kill-session -t etcd-server 2>/dev/null || true"\n\t@echo "✅ etcd-server stopped"\n', '# ════════════════════════════════════════════════════════════════════════════\n# [ETCD-VM-D317] DEBT-ETCD-HA-TLS-RAFT-001 paso 6b: el etcd-server corre en la VM etcd como ml-defender-etcd-server.service\n# (Vagrantfile, [ETCD-SERVER-UNIT-D317]), junto a etcd y Vault. El binario se compila en el defender (única máquina que\n# compila) y etcd-vm-deploy lo lleva a la VM. Estado real (no procesos): scripts/etcd_ha/etcd_vm_estado.sh.\n#   ETCD_VM_ESPERA_S: segundos que etcd-vm-check y etcd-vm-aviso esperan a que todo esté sano (entero [0, 300], defecto 30)\n# ════════════════════════════════════════════════════════════════════════════\nETCD_VM_ESPERA_S ?= 30\nETCD_VM_UNIDAD := ml-defender-etcd-server.service\nETCD_VM_ESTADO := /vagrant/scripts/etcd_ha/etcd_vm_estado.sh\n.PHONY: etcd-vm-deploy etcd-vm-estado etcd-vm-check etcd-vm-aviso\n\n# Mac: binario + librerías + material (d312_etcd_vm_deploy.sh), JSON por Ansible (deploy-configs), reinicio y control estricto\netcd-vm-deploy:\n\t@bash scripts/etcd_ha/d312_etcd_vm_deploy.sh $(PROFILE)\n\t@$(MAKE) --no-print-directory deploy-configs\n\t@vagrant ssh etcd -c "sudo systemctl restart $(ETCD_VM_UNIDAD)"\n\t@$(MAKE) --no-print-directory etcd-vm-check\n\n# Informe (rc 0 siempre)\netcd-vm-estado:\n\t@vagrant ssh etcd -c "bash $(ETCD_VM_ESTADO)"\n\n# Estricto (EMECAS): rc 1 si etcd-server, algún miembro etcd o Vault no están sanos tras ETCD_VM_ESPERA_S\netcd-vm-check:\n\t@vagrant ssh etcd -c "bash $(ETCD_VM_ESTADO) --estricto --esperar $(ETCD_VM_ESPERA_S)"\n\n# pipeline-start: informa y, si no está sano (o la VM está parada), avisa claro y sigue (decisión 4 de Alonso, DAY317)\netcd-vm-aviso:\n\t@vagrant ssh etcd -c "bash $(ETCD_VM_ESTADO) --estricto --esperar $(ETCD_VM_ESPERA_S)" > /tmp/argus_etcd_vm_aviso.txt 2>&1; rc=$$?; \\\n\t  cat /tmp/argus_etcd_vm_aviso.txt; \\\n\t  if [ $$rc -ne 0 ]; then \\\n\t    echo "[ETCD-VM-AVISO] la VM etcd NO está sana (o está parada): los componentes arrancan y protegen, pero sin clave HMAC no"; \\\n\t    echo "[ETCD-VM-AVISO] firman bronce ni CSV hasta que vuelvan etcd-server, etcd y Vault. Ver: make etcd-vm-estado; VM parada: vagrant up etcd"; \\\n\t  fi\n\netcd-server-start:  # [ETCD-VM-D317] arranca el servicio de la VM etcd y exige que quede sano\n\t@vagrant ssh etcd -c "sudo systemctl start $(ETCD_VM_UNIDAD)"\n\t@$(MAKE) --no-print-directory etcd-vm-check\n\netcd-server-stop:  # [ETCD-VM-D317] para el servicio de la VM etcd (Restart=always no lo relanza tras un stop explícito)\n\t@vagrant ssh etcd -c "sudo systemctl stop $(ETCD_VM_UNIDAD); echo \\"etcd-server de la VM etcd: \\$$(systemctl is-active $(ETCD_VM_UNIDAD))\\""\n')]
NUEVOS = {'scripts/etcd_ha/etcd_vm_estado.sh': '#!/bin/bash\n# etcd_vm_estado.sh — DAY317, paso 6b/6c de DEBT-ETCD-HA-TLS-RAFT-001: estado REAL de la VM etcd (no solo procesos).\n# Se ejecuta EN LA VM etcd como vagrant (hace sudo dentro): vagrant ssh etcd -c "bash /vagrant/scripts/etcd_ha/etcd_vm_estado.sh"\n#   - etcd-server: unidad systemd activa y GET /health por mTLS (certificado del propio etcd-server, regla «cualquiera»)\n#   - etcd: por cada miembro (etcdctl member list: con el PR2 salen todos), sano o no, líder, term y retraso respecto al líder\n#   - vault-hmac: por cada dirección de almacen_claves.vault_addrs, /v1/sys/health (200 activo, 429 en espera, 503 sellado)\n# Direcciones y certificados salen del JSON del etcd-server (el que escribe Ansible): el JSON es la ley.\n# Opciones: --estricto        rc 1 si algo no está sano (EMECAS); sin ella, rc 0 siempre (pipeline-status informa)\n#           --esperar S       reintenta hasta S segundos a que todo esté sano, entero [0, 300], defecto 0\n#           --retraso-max N   entradas de retraso respecto al líder que aún cuentan como sincronizado, entero [0, 1000000],\n#                             defecto 1000\nset -u\nLC_ALL=C; export LC_ALL\nJSON=/etc/ml-defender/etcd-server/etcd-server.json\nUNIDAD=ml-defender-etcd-server.service\nESTRICTO=no; ESPERAR=""; RETRASO=""\nwhile [ $# -gt 0 ]; do\n  case "$1" in\n    --estricto) ESTRICTO=si; shift;;\n    --esperar) ESPERAR=${2:-}; shift 2 || shift;;\n    --retraso-max) RETRASO=${2:-}; shift 2 || shift;;\n    *) echo "[ETCD-VM-ESTADO] opción desconocida \'$1\' (--estricto | --esperar S | --retraso-max N)"; exit 2;;\n  esac\ndone\nentero() {  # nombre valor defecto min max -> deja VAL y ORIGEN (sin subshell)\n  local n=$1 v=$2 d=$3 lo=$4 hi=$5\n  if [ -z "$v" ]; then VAL=$d; ORIGEN="defecto: ausente"; return; fi\n  if ! [[ "$v" =~ ^[0-9]+$ ]] || [ "$v" -lt "$lo" ] || [ "$v" -gt "$hi" ]; then\n    VAL=$d; ORIGEN="defecto: \'$v\' mal formado, entero en [$lo, $hi]"; return\n  fi\n  VAL=$v; ORIGEN="argumento"\n}\nentero esperar "$ESPERAR" 0 0 300;            ESPERAR=$VAL;   O_ESP=$ORIGEN\nentero retraso-max "$RETRASO" 1000 0 1000000; RETRASO_V=$VAL; O_RET=$ORIGEN\necho "[ETCD-VM-ESTADO] $(date -u +%FT%TZ) $(hostname) estricto=$ESTRICTO esperar_s=$ESPERAR ($O_ESP) retraso_max=$RETRASO_V ($O_RET)"\n\nif ! sudo test -f "$JSON"; then\n  echo "  ❌ etcd-server:   STOPPED [VM etcd: falta $JSON; despliegue: make etcd-vm-deploy desde el Mac]"\n  [ "$ESTRICTO" = si ] && exit 1 || exit 0\nfi\nCFG=$(sudo python3 - "$JSON" <<\'PY\'\nimport json, sys\nj = json.load(open(sys.argv[1]))\na, c, t, s = j["almacen"], j["almacen_claves"], j["tls"], j["server"]\nprint(",".join(a["endpoints"])); print(a["ca_file"]); print(a["cert_file"]); print(a["key_file"])\nprint(" ".join(c["vault_addrs"])); print(c["ca_file"]); print(c["cert_file"]); print(c["key_file"])\nprint(t["ca_file"]); print(t["cert_file"]); print(t["key_file"]); print(s["port"])\nPY\n) || { echo "  ❌ etcd-server:   STOPPED [VM etcd: $JSON ilegible o sin almacen/almacen_claves/tls/server]"; [ "$ESTRICTO" = si ] && exit 1 || exit 0; }\n{ read -r A_EP; read -r A_CA; read -r A_CRT; read -r A_KEY; read -r V_ADDRS; read -r V_CA; read -r V_CRT; read -r V_KEY\n  read -r T_CA; read -r T_CRT; read -r T_KEY; read -r PUERTO; } <<< "$CFG"\n\nevaluar() {  # deja el informe en INFORME y SANO=si|no\n  local ok=si l\n  INFORME=""\n  # etcd-server\n  local act code\n  act=$(systemctl is-active "$UNIDAD" 2>/dev/null)\n  code=$(sudo curl -s -o /dev/null -w \'%{http_code}\' --max-time 3 --cacert "$T_CA" --cert "$T_CRT" --key "$T_KEY" \\\n         "https://127.0.0.1:$PUERTO/health" 2>/dev/null)\n  if [ "$act" = active ] && [ "$code" = 200 ]; then\n    INFORME+="  ✅ etcd-server:   RUNNING [VM etcd: systemd active, /health $code]"$\'\\n\'\n  elif [ "$act" = active ]; then\n    INFORME+="  ⚠️  etcd-server:   RUNNING sin servicio [VM etcd: systemd active, /health ${code:-sin respuesta}]"$\'\\n\'; ok=no\n  else\n    INFORME+="  ❌ etcd-server:   STOPPED [VM etcd: systemd ${act:-desconocido}, /health ${code:-sin respuesta}]"$\'\\n\'; ok=no\n  fi\n  # etcd: miembros, salud, líder, retraso\n  local E="sudo etcdctl --endpoints=$A_EP --cacert=$A_CA --cert=$A_CRT --key=$A_KEY --command-timeout=3s -w json"\n  local ml st he\n  ml=$($E member list 2>/dev/null); st=$($E endpoint status --cluster 2>/dev/null); he=$($E endpoint health --cluster 2>/dev/null)\n  l=$(python3 - "$RETRASO_V" "$ml" "$st" "$he" <<\'PY\'\nimport json, sys\nrmax = int(sys.argv[1])\ndef carga(x):\n    try: return json.loads(x)\n    except Exception: return None\nml, st, he = carga(sys.argv[2]), carga(sys.argv[3]), carga(sys.argv[4])\nif not ml or "members" not in ml:\n    print("NO"); print("  ❌ etcd:          sin respuesta a member list (etcd caído o certificado rechazado)"); sys.exit()\nmiembros = {str(m["ID"]): m for m in ml["members"]}\nsanos = {h["endpoint"]: h.get("health", False) for h in (he or [])}\nestados = {str(s["Status"]["header"]["member_id"]): s for s in (st or [])}\nlideres = {str(s["Status"].get("leader", 0)) for s in estados.values()} - {"0"}\nlider = next(iter(lideres)) if len(lideres) == 1 else None\nidx_lider = estados[lider]["Status"]["raftIndex"] if lider in estados else None\nlineas, n_sanos, rmax_visto, ok = [], 0, 0, True\nfor mid, m in sorted(miembros.items(), key=lambda kv: kv[1].get("name", "")):\n    url = (m.get("clientURLs") or ["?"])[0]\n    s = estados.get(mid)\n    sano = bool(sanos.get(url)) and s is not None\n    if sano: n_sanos += 1\n    if s:\n        S = s["Status"]; ap = S.get("raftAppliedIndex", S["raftIndex"])\n        ret = (idx_lider - ap) if idx_lider is not None else None\n        if ret is not None: rmax_visto = max(rmax_visto, ret)\n        lineas.append("       - %s %s %s%s term=%s indice=%s aplicado=%s retraso=%s" % (\n            m.get("name", "?"), url, "sano" if sano else "NO SANO", " lider" if mid == lider else "",\n            S["raftTerm"], S["raftIndex"], ap, "?" if ret is None else ret))\n    else:\n        lineas.append("       - %s %s NO RESPONDE" % (m.get("name", "?"), url))\nif lider is None or n_sanos != len(miembros) or rmax_visto > rmax: ok = False\nnombre_lider = miembros[lider].get("name", "?") if lider in miembros else ("varios: %d" % len(lideres) if lideres else "ninguno")\nterm = estados[lider]["Status"]["raftTerm"] if lider in estados else "?"\nprint("SI" if ok else "NO")\nprint("  %s etcd:          %d/%d miembros sanos, líder %s (term %s), retraso máx %d entradas (límite %d)" % (\n    "✅" if ok else "❌", n_sanos, len(miembros), nombre_lider, term, rmax_visto, rmax))\nfor x in lineas: print(x)\nPY\n)\n  [ "$(printf \'%s\\n\' "$l" | head -n 1)" = SI ] || ok=no\n  INFORME+="$(printf \'%s\\n\' "$l" | tail -n +2)"$\'\\n\'\n  # Vault (claves HMAC): cada dirección del JSON\n  local a c nodos=0 activos=0 malos=0 det=""\n  for a in $V_ADDRS; do\n    nodos=$((nodos+1))\n    c=$(sudo curl -s -o /dev/null -w \'%{http_code}\' --max-time 3 --cacert "$V_CA" --cert "$V_CRT" --key "$V_KEY" \\\n        "$a/v1/sys/health" 2>/dev/null)\n    case "$c" in\n      200) activos=$((activos+1)); det+=" $a activo ($c);";;\n      429) det+=" $a en espera ($c);";;\n      503) malos=$((malos+1)); det+=" $a SELLADO ($c);";;\n      501) malos=$((malos+1)); det+=" $a SIN INICIALIZAR ($c);";;\n      *)   malos=$((malos+1)); det+=" $a sin respuesta (${c:-000});";;\n    esac\n  done\n  if [ "$activos" = 1 ] && [ "$malos" = 0 ]; then\n    INFORME+="  ✅ vault-hmac:    $nodos nodos, 1 activo:$det"$\'\\n\'\n  else\n    INFORME+="  ❌ vault-hmac:    $nodos nodos, $activos activos, $malos con problemas:$det"$\'\\n\'; ok=no\n  fi\n  SANO=$ok\n}\n\nT0=$(date +%s)\nwhile :; do\n  evaluar\n  [ "$SANO" = si ] && break\n  [ $(( $(date +%s) - T0 )) -ge "$ESPERAR" ] && break\n  sleep 2\ndone\nprintf \'%s\' "$INFORME"\nif [ "$SANO" = si ]; then\n  echo "[ETCD-VM-ESTADO] SANO tras $(( $(date +%s) - T0 )) s"\nelse\n  echo "[ETCD-VM-ESTADO] NO SANO tras $(( $(date +%s) - T0 )) s: el pipeline sigue protegiendo, pero sin etcd-server/etcd/Vault sanos no se firma con HMAC"\nfi\n[ "$ESTRICTO" = si ] && [ "$SANO" != si ] && exit 1\nexit 0\n'}   # {ruta: contenido}: ficheros que se crean (0755)

def sha(b):
    return hashlib.sha256(b).hexdigest()

def main():
    if len(sys.argv) != 3 or sys.argv[1] not in ('--check', '--apply'):
        sys.exit('uso: %s --check|--apply <raiz_repo>' % sys.argv[0])
    modo, raiz = sys.argv[1], sys.argv[2]
    mk = os.path.join(raiz, 'Makefile')
    if not os.path.isfile(mk):
        print('FALLA: no existe %s; no se toca nada.' % mk); return 1
    b = open(mk, 'rb').read()
    nuevos_ya = all(os.path.isfile(os.path.join(raiz, r)) and open(os.path.join(raiz, r), 'rb').read() == c.encode()
                    for r, c in NUEVOS.items())
    if sha(b) == MAKEFILE_FINAL and nuevos_ya:
        print('YA APLICADO: no se toca nada.'); return 0
    if sha(b) != MAKEFILE_PREVIO:
        print('FALLA: Makefile no está en el estado esperado (sha256 %s); no se toca nada.' % sha(b)[:16]); return 1
    for r in NUEVOS:
        if os.path.exists(os.path.join(raiz, r)):
            print('FALLA: %s ya existe con otro contenido; no se toca nada.' % r); return 1
    t = b.decode('utf-8')
    for i, (v, n) in enumerate(CAMBIOS, 1):
        if t.count(v) != 1:
            print('FALLA: el cambio %d encuentra su texto %d veces (se exige 1); no se toca nada.' % (i, t.count(v))); return 1
        t = t.replace(v, n)
    nuevo = t.encode('utf-8')
    if sha(nuevo) != MAKEFILE_FINAL:
        print('FALLA: el Makefile resultante no da el sha256 final; no se toca nada.'); return 1
    if modo == '--check':
        print('APLICABLE: Makefile (%d cambios)%s.' % (len(CAMBIOS), ''.join(' + %s nuevo' % r for r in NUEVOS))); return 0
    for r, c in NUEVOS.items():
        f = os.path.join(raiz, r); tmp = f + '.d317tmp'
        with open(tmp, 'wb') as o: o.write(c.encode('utf-8'))
        os.chmod(tmp, 0o755); os.replace(tmp, f); print('  creado   %s' % r)
    tmp = mk + '.d317tmp'
    with open(tmp, 'wb') as o: o.write(nuevo)
    os.chmod(tmp, os.stat(mk).st_mode & 0o7777); os.replace(tmp, mk); print('  escrito  Makefile')
    if sha(open(mk, 'rb').read()) != MAKEFILE_FINAL:
        print('FALLA tras escribir el Makefile'); return 1
    print('APLICADO: Makefile (sha256 %s)%s.' % (MAKEFILE_FINAL[:16], ''.join(' + %s' % r for r in NUEVOS))); return 0

if __name__ == '__main__':
    sys.exit(main())
